const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; // 10" x 5.625"
pres.author = 'Gemini';
pres.title = 'Global CO₂ Emissions';

// Define Color Palette
const COLORS = {
  darkBg: "1E2761", // Navy
  lightBg: "F8FAFC", // Off-white
  accent: "D1345B", // Red/coral
  textDark: "1E293B",
  textLight: "FFFFFF",
  textMuted: "64748B",
  chartBlue: "028090",
  chartTeal: "00A896",
  chartMint: "02C39A",
  chartNavy: "21295C",
  chartOrange: "F96167",
  gridLine: "E2E8F0"
};

// Define Masters
pres.defineSlideMaster({
  title: 'TITLE_SLIDE',
  background: { color: COLORS.darkBg },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: '0.15', fill: { color: COLORS.accent } } }
  ]
});

pres.defineSlideMaster({
  title: 'CONTENT_SLIDE',
  background: { color: COLORS.lightBg },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: '0.08', fill: { color: COLORS.chartBlue } } },
    { text: { text: "Data: Global Carbon Budget 2025 via Our World in Data", options: { x: 0.5, y: 5.3, w: 9, h: 0.2, fontSize: 10, color: COLORS.textMuted, align: 'left', margin: 0 } } }
  ]
});

pres.defineSlideMaster({
  title: 'CONCLUSION_SLIDE',
  background: { color: COLORS.darkBg },
  objects: [
    { rect: { x: 0, y: 5.475, w: '100%', h: '0.15', fill: { color: COLORS.accent } } }
  ]
});

// SLIDE 1: Title Slide
let slide1 = pres.addSlide({ masterName: "TITLE_SLIDE" });
slide1.addText("Global CO₂ Emissions: Who Emits, How Much, and What's Changing", {
  x: 0.5, y: 1.8, w: 9, h: 1.5,
  fontSize: 44, fontFace: "Georgia", bold: true, color: COLORS.textLight, breakLine: true, margin: 0
});
slide1.addText("A data-driven overview from the Industrial Revolution (1750) to 2024", {
  x: 0.5, y: 3.4, w: 9, h: 0.5,
  fontSize: 20, fontFace: "Calibri", color: COLORS.chartMint, margin: 0
});
slide1.addText([
  { text: "Prepared for: Policy Analysts, Climate Negotiators, and Sustainability Researchers", options: { breakLine: true } },
  { text: "Data: Global Carbon Budget 2025 via Our World in Data" }
], {
  x: 0.5, y: 4.5, w: 9, h: 0.8,
  fontSize: 14, fontFace: "Calibri", color: "CADCFC", margin: 0
});

// SLIDE 2: Global Emissions Growth
let slide2 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide2.addText("Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today", {
  x: 0.5, y: 0.4, w: 9, h: 0.8, fontSize: 32, fontFace: "Georgia", bold: true, color: COLORS.textDark, margin: 0
});
slide2.addText("Total global CO₂ emissions from fossil fuels and industry", {
  x: 0.5, y: 1.2, w: 9, h: 0.3, fontSize: 16, fontFace: "Calibri", color: COLORS.textMuted, margin: 0
});

const slide2Data = [{
  name: "Global CO₂ Emissions (Bt)",
  labels: ["1750", "1850", "1900", "1950", "1990", "2024"],
  values: [0.01, 0.2, 2.0, 6.0, 20.0, 35.0]
}];
slide2.addChart(pres.charts.LINE, slide2Data, {
  x: 0.5, y: 1.8, w: 9, h: 3.2,
  chartColors: [COLORS.chartOrange],
  lineSize: 4, lineSmooth: true,
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valGridLine: { color: COLORS.gridLine, size: 0.5 },
  catGridLine: { style: "none" },
  catAxisLabelColor: COLORS.textMuted,
  valAxisLabelColor: COLORS.textMuted,
  showValue: true, dataLabelPosition: "t", dataLabelColor: COLORS.textDark,
  showLegend: false
});

// SLIDE 3: Regional Share Shift
let slide3 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide3.addText("Europe and the US Fell from 90% of Emissions in 1900 to Under One-Third Today", {
  x: 0.5, y: 0.4, w: 9, h: 0.8, fontSize: 30, fontFace: "Georgia", bold: true, color: COLORS.textDark, margin: 0
});

slide3.addText("Dramatic shift in regional emission shares over time", {
  x: 0.5, y: 1.1, w: 9, h: 0.3, fontSize: 16, fontFace: "Calibri", color: COLORS.textMuted, margin: 0
});

const slide3Data = [
  { name: "Europe & US", labels: ["1900", "1950", "2000", "2024"], values: [92, 86, 50, 31] },
  { name: "Asia (led by China)", labels: ["1900", "1950", "2000", "2024"], values: [3, 6, 35, 52] }
];
slide3.addChart(pres.charts.LINE, slide3Data, {
  x: 0.5, y: 1.6, w: 6, h: 3.5,
  chartColors: [COLORS.chartBlue, COLORS.chartMint],
  lineSize: 3, lineSmooth: true,
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valGridLine: { color: COLORS.gridLine, size: 0.5 },
  catGridLine: { style: "none" },
  catAxisLabelColor: COLORS.textMuted,
  valAxisLabelColor: COLORS.textMuted,
  showLegend: true, legendPos: "b"
});

// Callout
slide3.addShape(pres.shapes.RECTANGLE, { x: 7, y: 2, w: 2.5, h: 2, fill: { color: "FFFFFF" }, shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 }});
slide3.addText([
  { text: "1900:\n", options: { fontSize: 16, bold: true, color: COLORS.chartBlue } },
  { text: "US & Europe: >90%\n\n", options: { fontSize: 14 } },
  { text: "2024:\n", options: { fontSize: 16, bold: true, color: COLORS.chartMint } },
  { text: "Asia dominates with roughly 50% of global total.", options: { fontSize: 14 } }
], { x: 7.2, y: 2.2, w: 2.1, h: 1.6, color: COLORS.textDark, align: "left" });

// SLIDE 4: China Dominates Share
let slide4 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide4.addText("China Now Emits More Than One-Quarter of Global CO₂", {
  x: 0.5, y: 0.4, w: 9, h: 0.8, fontSize: 32, fontFace: "Georgia", bold: true, color: COLORS.textDark, margin: 0
});
slide4.addText("Approximate Share of Global CO₂ Emissions (2024)", {
  x: 0.5, y: 1.2, w: 9, h: 0.3, fontSize: 16, fontFace: "Calibri", color: COLORS.textMuted, margin: 0
});

const slide4Data = [{
  name: "Share",
  labels: ["China", "United States", "India", "EU-27", "Russia", "Africa", "South America", "Aviation/Ship"],
  values: [31, 13, 8, 6, 5, 4, 4, 3]
}];
slide4.addChart(pres.charts.BAR, slide4Data, {
  x: 0.5, y: 1.8, w: 9, h: 3.2, barDir: "col",
  chartColors: [COLORS.chartOrange],
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valGridLine: { color: COLORS.gridLine, size: 0.5 },
  catGridLine: { style: "none" },
  catAxisLabelColor: COLORS.textMuted, valAxisLabelColor: COLORS.textMuted,
  showValue: true, dataLabelPosition: "outEnd", dataLabelColor: COLORS.textDark,
  showLegend: false
});

pres.writeFile({ fileName: "/app/output/final_deck.pptx" }).then(() => {
    console.log('Done');
});

